    "thirteen",
    "fourteen",
    "fifteen",
    "sixteen",
    "seventeen",
    "eighteen",
    "nineteen",
];

const TENS: [&str; 10] = [
    "",
    "ten",
    "twenty",
    "thirty",
    "forty",
    "fifty",
    "sixty",
    "seventy",
    "eighty",
    "ninety",
];

const SCALES: [&str; 7] = [
    "",
    "thousand",
    "million",
    "billion",
    "trillion",
    "quadrillion",
    "quintillion",
];

fn under_thousand(n: u64) -> String {
    let mut parts = Vec::new();

    if n >= 100 {
        parts.push(UNITS[(n / 100) as usize]);
        parts.push("hundred");
        n %= 100;
        if n > 0 {
            parts.push("-");
        }
    }

    if n >= 20 {
        let tens = (n / 10) as usize;
        let ones = (n % 10) as usize;
        if ones > 0 {
            parts.push(TENS[tens]);
            parts.push("-");
            parts.push(UNITS[ones]);
        } else {
            parts.push(TENS[tens]);
        }
    } else if n > 0 {
        parts.push(UNITS[n as usize]);
    }

    parts.join(" ")
}

pub fn encode(n: u64) -> String {
    if n == 0 {
        return "zero".to_string();
    }

    let mut parts = Vec::new();
    let mut scale = 0;

    while n > 0 {
        let chunk = n % 1000;
        if chunk > 0 {
            let mut part = under_thousand(chunk);
            if scale > 0 {
                part.push_str(" ");
                part.push_str(SCALES[scale]);
            }
            parts.push(part);
        }
        n /= 1000;
        scale += 1;
    }

    parts.reverse();
    parts.join(" ")
}

